windowclass.script:
function onInit()
  self.onLockModeChanged(WindowManager.getWindowReadOnlyState(self));
end
function onLockModeChanged(bReadOnly)
  WindowManager.callSafeControlsSetLockMode(self, { "list_iadd", }, bReadOnly);
end

      function onInit()
        self.onLockModeChanged(WindowManager.getWindowReadOnlyState(self));
      end
      function onLockModeChanged(bReadOnly)
        WindowManager.callSafeControlsSetLockMode(self, { "name", "modifier", "idelete" }, bReadOnly);
      end
			function actionDrag(draginfo)
				if not name.isEmpty() then
					draginfo.setType("number");
					draginfo.setDescription(name.getValue());
					draginfo.setStringData(name.getValue());
					draginfo.setNumberData(modifier.getValue());
				end
				return true;
			end
			function action()
				ModifierStack.addSlot(name.getValue(), modifier.getValue());
				return true;
			end
			function onDrop(x, y, draginfo)
				return windowlist.onDrop(x, y, draginfo);
			end

button_listitem_right.script:
          function onDragStart(button, x, y, draginfo)
						return window.actionDrag(draginfo);
					end

					function onButtonPress(x, y)
						return window.action();
					end
